type": ["number", "null"], "default": null, "description": "точка наблюдения для p(t), м"}, "views": {"type": "array", "items": {"enum": ["profile", "history", "plan"]}, "default": ["profile", "history"]}, "history_points": {"type": "array", "items": {"enum": ["obs", "well"]}, "default": ["obs"], "description": "что показывать на p(t): точку наблюдения и/или забой"}, "show_front": {"type": "boolean", "default": true, "description": "граница возмущённой области ПССС"}, "show_flow": {"type": "boolean", "default": true}}}

